// Types for the Blue Reacher API (https://docs.bluereacher.com).
// Generated by hand from the public OpenAPI spec, version 2026-08-27.

/** Pace a send through the drip pipeline (default) or dispatch it now. */
export type SendMode = "drip" | "instant";

/** Optional iMessage effect the line arms before an instant send. */
export type MessageEffect =
  | "confetti"
  | "balloons"
  | "love"
  | "lasers"
  | "fireworks"
  | "celebration"
  | "echo"
  | "spotlight"
  | "slam"
  | "loud"
  | "gentle"
  | "invisibleink";

export interface SendMessageParams {
  /** Recipient in E.164 format for a 1:1 send. Pass exactly one of `to`, `groupChatId`, `createGroupPhones`. */
  to?: string;
  /** Existing group chat id (from `listGroups`). Instant only. */
  groupChatId?: string;
  /** 2 to 25 E.164 numbers: creates a new group iMessage, then sends. Instant only. */
  createGroupPhones?: string[];
  /** Message text. Required unless `mediaUrls` is set. */
  message?: string;
  /** 1 to 10 https:// URLs to attach. */
  mediaUrls?: string[];
  /** `drip` (default) paces through the pipeline; `instant` dispatches now. */
  sendMode?: SendMode;
  /** Requires `sendMode: "instant"`. */
  messageEffect?: MessageEffect;
  /** Explicit line id to send from. Omit to let Blue Reacher route. */
  deviceId?: string;
  /** Minutes to schedule a drip send out (default about 10). */
  delayMinutes?: number;
  /** Optional idempotency key, echoed as the `Idempotency-Key` header. */
  idempotencyKey?: string;
}

export interface DripQueuedResult {
  success: boolean;
  /** Queue item id. Poll with `getStatus`. */
  messageId: string;
  mode: "drip";
  queued?: boolean;
  scheduledFor?: string;
  estimatedSendTime?: string;
  queuePosition?: number;
}

export interface InstantDispatchedResult {
  success: boolean;
  /** Message row id. Poll with `getStatus`. */
  messageId: string;
  mode: "instant";
  status?: "dispatched";
  deviceId?: string | null;
}

export type SendMessageResult = DripQueuedResult | InstantDispatchedResult;

export interface MessageStatus {
  success: boolean;
  messageId: string;
  type: "drip_queue" | "message" | "voice_memo";
  status: string;
  scheduledFor?: string | null;
  sentAt?: string | null;
  deviceName?: string | null;
  error?: string | null;
}

